//! Tests for src/snake.rs (15 tests). Do not edit this file.
//!
//! Run just these with: cargo test snake::

use super::*;

/// Collects the body into a Vec of (x, y) pairs, head first.
fn body_cells(snake: &Snake) -> Vec<(i32, i32)> {
    snake.body.iter().map(|b| (b.x, b.y)).collect()
}

// ---------- Phase 2: Direction ----------

#[test]
fn opposite_returns_reverse_direction() {
    assert_eq!(Direction::Up.opposite(), Direction::Down);
    assert_eq!(Direction::Down.opposite(), Direction::Up);
    assert_eq!(Direction::Left.opposite(), Direction::Right);
    assert_eq!(Direction::Right.opposite(), Direction::Left);
}

#[test]
fn opposite_twice_is_original_direction() {
    for dir in [
        Direction::Up,
        Direction::Down,
        Direction::Left,
        Direction::Right,
    ] {
        assert_eq!(dir.opposite().opposite(), dir);
    }
}

// ---------- Phase 3: creating the snake ----------

#[test]
fn new_snake_has_three_blocks() {
    let snake = Snake::new(2, 2);
    assert_eq!(snake.body.len(), 3);
}

#[test]
fn new_snake_faces_right_and_has_no_tail_yet() {
    let snake = Snake::new(2, 2);
    assert_eq!(snake.head_direction(), Direction::Right);
    assert_eq!(snake.tail, None);
}

#[test]
fn new_snake_body_is_ordered_head_first() {
    let snake = Snake::new(5, 7);
    assert_eq!(body_cells(&snake), vec![(7, 7), (6, 7), (5, 7)]);
    assert_eq!(snake.head_position(), (7, 7));
}

// ---------- Phase 4: moving ----------

#[test]
fn move_forward_without_direction_keeps_going() {
    let mut snake = Snake::new(2, 2);
    snake.move_forward(None);
    assert_eq!(body_cells(&snake), vec![(5, 2), (4, 2), (3, 2)]);
    assert_eq!(snake.head_direction(), Direction::Right);
}

#[test]
fn move_forward_with_direction_turns_the_snake() {
    let mut snake = Snake::new(2, 2);
    snake.move_forward(Some(Direction::Down));
    assert_eq!(snake.head_direction(), Direction::Down);
    assert_eq!(body_cells(&snake), vec![(4, 3), (4, 2), (3, 2)]);
}

#[test]
fn move_forward_up_and_left() {
    let mut snake = Snake::new(2, 2);
    snake.move_forward(Some(Direction::Up));
    assert_eq!(snake.head_position(), (4, 1));
    snake.move_forward(Some(Direction::Left));
    assert_eq!(snake.head_position(), (3, 1));
    assert_eq!(snake.body.len(), 3);
}

#[test]
fn move_forward_remembers_removed_tail() {
    let mut snake = Snake::new(2, 2);
    snake.move_forward(None);
    assert_eq!(snake.tail, Some(Block { x: 2, y: 2 }));
    snake.move_forward(None);
    assert_eq!(snake.tail, Some(Block { x: 3, y: 2 }));
}

#[test]
fn next_head_does_not_move_the_snake() {
    let snake = Snake::new(2, 2);
    assert_eq!(snake.next_head(None), (5, 2));
    assert_eq!(snake.head_position(), (4, 2));
    assert_eq!(snake.head_direction(), Direction::Right);
    assert_eq!(snake.tail, None);
}

#[test]
fn next_head_uses_the_given_direction() {
    let snake = Snake::new(2, 2);
    assert_eq!(snake.next_head(Some(Direction::Up)), (4, 1));
    assert_eq!(snake.next_head(Some(Direction::Down)), (4, 3));
    assert_eq!(snake.next_head(Some(Direction::Left)), (3, 2));
    assert_eq!(snake.next_head(Some(Direction::Right)), (5, 2));
    // Looking ahead must not turn the snake.
    assert_eq!(snake.head_direction(), Direction::Right);
}

// ---------- Phase 5: growing and overlapping ----------

#[test]
fn restore_tail_grows_the_snake() {
    let mut snake = Snake::new(2, 2);
    snake.move_forward(None);
    snake.restore_tail();
    assert_eq!(body_cells(&snake), vec![(5, 2), (4, 2), (3, 2), (2, 2)]);
}

#[test]
fn overlap_tail_detects_body_blocks() {
    let snake = Snake::new(2, 2);
    assert!(snake.overlap_tail(4, 2), "the head should count");
    assert!(snake.overlap_tail(3, 2), "the middle block should count");
}

#[test]
fn overlap_tail_ignores_the_last_block() {
    let snake = Snake::new(2, 2);
    assert!(!snake.overlap_tail(2, 2));
}

#[test]
fn overlap_tail_is_false_for_empty_cells() {
    let snake = Snake::new(2, 2);
    assert!(!snake.overlap_tail(5, 2));
    assert!(!snake.overlap_tail(3, 3));
    assert!(!snake.overlap_tail(10, 10));
}
